    if($action==='select_invoice'){
        $branchId=(int)($_POST['branch_id']??0);$bhf=trim((string)($_POST['bhf_id']??''));$sdc=trim((string)($_POST['sdc_id']??''));$cis=trim((string)($_POST['cis_invoice']??''));$device=zra_admin_device($conn,$pharmacyId,$branchId,$env);if(!$device||(int)$device['initialized']!==1)zra_admin_redirect('', 'Initialize the branch device first.');$tpin=preg_replace('/\D+/','',(string)($settings['tpin']??''));$payload=['tpin'=>$tpin,'bhfId'=>$bhf,'invcSdcId'=>$sdc,'cisInvcNo'=>$cis];$res=zra_http_post((string)$device['base_url'],'/trnsSales/selectInvoice',$payload);zra_admin_log_api($conn,$pharmacyId,$branchId,null,'/trnsSales/selectInvoice',$res,$payload);if(!$res['ok'])zra_admin_redirect('', 'Invoice lookup failed: '.($res['error']??'Unknown error.'));$_SESSION['zra2_last_lookup']=$res['json'];zra_admin_redirect('ZRA invoice lookup completed.');
    }
}

$ok=(string)($_GET['ok']??'');$err=(string)($_GET['err']??'');
$branches=[];$s=$conn->prepare('SELECT id,branch_name FROM branches WHERE pharmacy_id=? ORDER BY branch_name');if($s){$s->bind_param('i',$pharmacyId);$s->execute();$r=$s->get_result();while($r&&($x=$r->fetch_assoc()))$branches[]=$x;$s->close();}
$devices=[];$s=$conn->prepare('SELECT d.*,b.branch_name FROM zra_devices d LEFT JOIN branches b ON b.id=d.branch_id AND b.pharmacy_id=d.pharmacy_id WHERE d.pharmacy_id=? ORDER BY b.branch_name');if($s){$s->bind_param('i',$pharmacyId);$s->execute();$r=$s->get_result();while($r&&($x=$r->fetch_assoc()))$devices[]=$x;$s->close();}
$queue=[];$s=$conn->prepare('SELECT q.*,b.branch_name FROM zra_queue q LEFT JOIN branches b ON b.id=q.branch_id AND b.pharmacy_id=q.pharmacy_id WHERE q.pharmacy_id=? ORDER BY q.id DESC LIMIT 100');if($s){$s->bind_param('i',$pharmacyId);$s->execute();$r=$s->get_result();while($r&&($x=$r->fetch_assoc()))$queue[]=$x;$s->close();}
$recentSales=[];$s=$conn->prepare('SELECT id,branch_id,invoice,created_at,total,payment_method FROM sales WHERE pharmacy_id=? ORDER BY id DESC LIMIT 50');if($s){$s->bind_param('i',$pharmacyId);$s->execute();$r=$s->get_result();while($r&&($x=$r->fetch_assoc()))$recentSales[]=$x;$s->close();}
$classesCount=0;$codesCount=0;if(zra_admin_table($conn,'zra_item_classes')){$s=$conn->prepare('SELECT COUNT(*) c FROM zra_item_classes WHERE pharmacy_id=?');if($s){$s->bind_param('i',$pharmacyId);$s->execute();$x=$s->get_result()->fetch_assoc();$classesCount=(int)($x['c']??0);$s->close();}}if(zra_admin_table($conn,'zra_standard_codes')){$s=$conn->prepare('SELECT COUNT(*) c FROM zra_standard_codes WHERE pharmacy_id=?');if($s){$s->bind_param('i',$pharmacyId);$s->execute();$x=$s->get_result()->fetch_assoc();$codesCount=(int)($x['c']??0);$s->close();}}
$current_admin_page='zra.php';$admin_page_title='ZRA Smart Invoice — ZRA Integration';$user_display_name=(string)($_SESSION['full_name']??$_SESSION['username']??'Administrator');$adminAside=__DIR__.'/../admin_aside.php';$adminHeader=__DIR__.'/../admin_header.php';
