<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ZRA Smart Invoice — ZRA Integration</title><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css"><style>
:root{--bg:#f4f6f9;--card:#fff;--text:#17202b;--muted:#718096;--border:#e3e8ef;--blue:#2563eb;--green:#059669;--red:#dc2626;--orange:#d97706;--shadow:0 4px 18px rgba(15,23,42,.06)}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:14px Inter,system-ui,-apple-system,"Segoe UI",sans-serif}.main{min-height:100vh}.wrap{padding:24px;max-width:1600px;margin:auto}.head{display:flex;justify-content:space-between;gap:18px;align-items:flex-start;margin-bottom:18px}.head h1{margin:0 0 5px;font-size:28px}.muted{color:var(--muted)}.btn{display:inline-flex;align-items:center;gap:7px;border:1px solid var(--border);background:#fff;color:var(--text);padding:9px 13px;border-radius:8px;text-decoration:none;font-weight:800;cursor:pointer}.btn.primary{background:var(--blue);border-color:var(--blue);color:#fff}.btn.green{background:var(--green);border-color:var(--green);color:#fff}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:16px}.card,.panel{background:#fff;border:1px solid var(--border);border-radius:12px;box-shadow:var(--shadow)}.card{padding:16px}.label{font-size:11px;text-transform:uppercase;color:var(--muted);font-weight:900}.value{font-size:26px;font-weight:900;margin-top:7px}.panel{overflow:hidden;margin-bottom:16px}.panel h2{font-size:17px;margin:0}.ph{padding:16px 18px;border-bottom:1px solid var(--border)}.pb{padding:18px}.alert{padding:12px 14px;border-radius:9px;margin-bottom:14px}.ok{background:#ecfdf5;color:#047857;border:1px solid #a7f3d0}.err{background:#fef2f2;color:#b91c1c;border:1px solid #fecaca}.fields{display:grid;grid-template-columns:repeat(2,1fr);gap:12px}.field{margin-bottom:11px}.field label{display:block;font-size:12px;font-weight:900;margin-bottom:6px}.field input,.field select{width:100%;padding:10px;border:1px solid #d9e0e8;border-radius:8px;font:inherit;background:#fff}.actions{display:flex;gap:8px;flex-wrap:wrap}.notice{padding:12px;border:1px solid #dbe5f3;background:#f7faff;border-radius:8px;color:#40566f;line-height:1.5;font-size:12px;margin-bottom:12px}table{width:100%;border-collapse:collapse}th,td{padding:10px;border-bottom:1px solid #edf0f4;text-align:left;font-size:12px}th{font-size:10px;text-transform:uppercase;color:#667789;background:#fafbfc}.badge{display:inline-block;padding:5px 8px;border-radius:999px;font-size:10px;font-weight:900}.bgreen{background:#eaf8f1;color:#047857}.borange{background:#fff7e6;color:#b45309}.bred{background:#fef0f0;color:#b91c1c}.bgray{background:#eef2f5;color:#5b6773}@media(max-width:1000px){.grid{grid-template-columns:repeat(2,1fr)}.fields{grid-template-columns:1fr}}@media(max-width:600px){.wrap{padding:14px}.grid{grid-template-columns:1fr}.head{flex-direction:column}.head h1{font-size:23px}}
</style></head><body><div class="app"><?php if(is_file($adminAside))require $adminAside; ?><main class="main"><?php if(is_file($adminHeader))require $adminHeader; ?><div class="wrap">
<div class="head"><div><div style="color:#2563eb;font-size:11px;font-weight:900;letter-spacing:.08em;text-transform:uppercase">Administration / ZRA</div><h1>Smart Invoice — ZRA Integration</h1><p class="muted">VSDC/OSDC integration, device initialization, reference data and controlled invoice submission.</p></div><div class="actions"><a class="btn" href="compliance.php"><i class="fa-solid fa-arrow-left"></i> Compliance</a><a class="btn primary" href="https://www.zra.org.zm/smart-invoice-learn-more/" target="_blank" rel="noopener"><i class="fa-solid fa-landmark"></i> ZRA</a></div></div>
<?php if($ok):?><div class="alert ok"><i class="fa-solid fa-circle-check"></i> <?=zra_admin_h($ok)?></div><?php endif;?><?php if($err):?><div class="alert err"><i class="fa-solid fa-circle-exclamation"></i> <?=zra_admin_h($err)?></div><?php endif;?>
<div class="grid"><div class="card"><div class="label">Environment</div><div class="value"><?=zra_admin_h(ucfirst($env))?></div><div class="muted">Configured in Compliance</div></div><div class="card"><div class="label">Devices</div><div class="value"><?=count($devices)?></div><div class="muted">Branch controllers</div></div><div class="card"><div class="label">Standard Codes</div><div class="value"><?=$codesCount?></div><div class="muted">Locally stored</div></div><div class="card"><div class="label">Classification Codes</div><div class="value"><?=$classesCount?></div><div class="muted">Locally stored</div></div></div>
<div class="panel"><div class="ph"><h2>ZRA Integration safety boundary</h2></div><div class="pb"><div class="notice"><b>Important:</b> ZRA Integration supports the official ZRA VSDC/OSDC interface, but live production transmission must only be enabled after the taxpayer/device has been approved and the EchoTech POS solution has completed the applicable ZRA integration/certification process. ZRA's current documentation identifies the VSDC as the bridge for certified third-party invoicing systems.</div><div class="notice">The controller is responsible for device initialization and signing. EchoTech stores encrypted device credentials and sends JSON requests to the configured controller. No ZRA private key is displayed in this page.</div></div></div>
<div class="panel"><div class="ph"><h2>1. Branch / ZRA device setup</h2></div><div class="pb"><form method="post"><input type="hidden" name="csrf" value="<?=zra_admin_h($_SESSION['zra_csrf'])?>"><input type="hidden" name="action" value="save_branch"><div class="fields"><div class="field"><label>POS Branch</label><select name="branch_id" required><option value="">Select branch</option><?php foreach($branches as $b):?><option value="<?=$b['id']?>"><?=zra_admin_h($b['branch_name'])?></option><?php endforeach;?></select></div><div class="field"><label>ZRA Branch ID (bhfId)</label><input name="zra_bhf_id" maxlength="3" required placeholder="000"></div></div><button class="btn primary"><i class="fa-solid fa-link"></i> Save Branch Mapping</button></form></div></div>
<div class="panel"><div class="ph"><h2>2. Initialize VSDC / OSDC device</h2><p class="muted">ZRA requires TPIN, 3-character branch ID and device serial for initialization.</p></div><div class="pb"><form method="post"><input type="hidden" name="csrf" value="<?=zra_admin_h($_SESSION['zra_csrf'])?>"><input type="hidden" name="action" value="initialize_device"><div class="fields"><div class="field"><label>Branch</label><select name="branch_id" id="initBranch" required onchange="setBhf(this)"><option value="">Select branch</option><?php foreach($branches as $b):?><option value="<?=$b['id']?>"><?=zra_admin_h($b['branch_name'])?></option><?php endforeach;?></select></div><div class="field"><label>ZRA bhfId</label><input name="bhf_id" id="bhf" maxlength="3" required placeholder="000"></div><div class="field"><label>Device Serial Number</label><input name="device_serial" maxlength="100" required></div><div class="field"><label>VSDC / OSDC Base URL</label><input name="base_url" value="<?=zra_admin_h($baseUrl)?>" required placeholder="http://localhost:8080/zraVsdc..."></div></div><button class="btn green"><i class="fa-solid fa-plug"></i> Initialize Device</button></form></div></div>
<div class="panel"><div class="ph"><h2>3. Reference data</h2><p class="muted">ZRA requires standard codes and classification codes to be stored locally before transaction/item integration.</p></div><div class="pb"><div class="fields"><form method="post"><input type="hidden" name="csrf" value="<?=zra_admin_h($_SESSION['zra_csrf'])?>"><input type="hidden" name="action" value="sync_codes"><div class="field"><label>Branch</label><select name="branch_id" required><option value="">Select branch</option><?php foreach($devices as $d):?><option value="<?=zra_admin_h($d['branch_id'])?>"><?=zra_admin_h($d['branch_name']??$d['branch_id'])?> — <?=zra_admin_h($d['bhf_id'])?></option><?php endforeach;?></select></div><div class="field"><label>bhfId</label><input name="bhf_id" maxlength="3" required></div><button class="btn"><i class="fa-solid fa-arrows-rotate"></i> Sync Standard Codes</button></form><form method="post"><input type="hidden" name="csrf" value="<?=zra_admin_h($_SESSION['zra_csrf'])?>"><input type="hidden" name="action" value="sync_classes"><div class="field"><label>Branch</label><select name="branch_id" required><option value="">Select branch</option><?php foreach($devices as $d):?><option value="<?=zra_admin_h($d['branch_id'])?>"><?=zra_admin_h($d['branch_name']??$d['branch_id'])?> — <?=zra_admin_h($d['bhf_id'])?></option><?php endforeach;?></select></div><div class="field"><label>bhfId</label><input name="bhf_id" maxlength="3" required></div><button class="btn"><i class="fa-solid fa-list"></i> Sync Classification Codes</button></form></div></div></div>
<div class="panel"><div class="ph"><h2>Configured devices</h2></div><div class="pb" style="overflow:auto"><table><thead><tr><th>Branch</th><th>bhfId</th><th>Environment</th><th>Device</th><th>SDC</th><th>Status</th></tr></thead><tbody><?php if(!$devices):?><tr><td colspan="6" class="muted">No ZRA devices initialized.</td></tr><?php else:foreach($devices as $d):?><tr><td><?=zra_admin_h($d['branch_name']??$d['branch_id'])?></td><td><?=zra_admin_h($d['bhf_id'])?></td><td><?=zra_admin_h($d['environment'])?></td><td><?=zra_admin_h($d['device_serial'])?></td><td><?=zra_admin_h($d['sdc_id']??'-')?></td><td><span class="badge <?=((int)$d['initialized']===1)?'bgreen':'bred'?>"><?=((int)$d['initialized']===1)?'Initialized':'Not initialized'?></span></td></tr><?php endforeach;endif;?></tbody></table></div></div>
<div class="panel"><div class="ph"><h2>4. POS sales submission queue</h2><p class="muted">Sales are built from the authoritative EchoTech sales/sales_items records and are isolated by pharmacy and branch.</p></div><div class="pb"><form method="post" class="fields" style="margin-bottom:15px"><input type="hidden" name="csrf" value="<?=zra_admin_h($_SESSION['zra_csrf'])?>"><input type="hidden" name="action" value="queue_sale"><div class="field"><label>Recent Sale</label><select name="sale_id" required><?php foreach($recentSales as $s):?><option value="<?=$s['id']?>">#<?=$s['id']?> — <?=zra_admin_h($s['invoice'])?> — K<?=number_format((float)$s['total'],2)?> — <?=zra_admin_h($s['payment_method'])?></option><?php endforeach;?></select></div><div class="field"><label>Branch / ZRA bhfId</label><select name="branch_id" required onchange="setQueueBhf(this)"><option value="">Select branch</option><?php foreach($branches as $b):?><option value="<?=$b['id']?>"><?=zra_admin_h($b['branch_name'])?></option><?php endforeach;?></select><input name="bhf_id" id="queueBhf" maxlength="3" required placeholder="000" style="margin-top:7px"></div><div><button class="btn primary" style="margin-top:24px"><i class="fa-solid fa-layer-group"></i> Queue Sale</button></div></form><div style="overflow:auto"><table><thead><tr><th>ID</th><th>Sale</th><th>Branch</th><th>Endpoint</th><th>Status</th><th>Attempts</th><th>Action</th></tr></thead><tbody><?php if(!$queue):?><tr><td colspan="7" class="muted">No queued ZRA transactions.</td></tr><?php else:foreach($queue as $q):?><tr><td><?=$q['id']?></td><td><?=zra_admin_h($q['local_reference'])?></td><td><?=zra_admin_h($q['branch_name']??$q['branch_id'])?></td><td><?=zra_admin_h($q['endpoint'])?></td><td><span class="badge <?=in_array($q['status'],['submitted'])?'bgreen':(in_array($q['status'],['rejected','failed'])?'bred':'borange')?>"><?=zra_admin_h($q['status'])?></span></td><td><?=$q['attempts']?></td><td><?php if(in_array($q['status'],['queued','failed','rejected'])):?><form method="post"><input type="hidden" name="csrf" value="<?=zra_admin_h($_SESSION['zra_csrf'])?>"><input type="hidden" name="action" value="submit_queue"><input type="hidden" name="queue_id" value="<?=$q['id']?>"><button class="btn green">Submit</button></form><?php else:?>-<?php endif;?></td></tr><?php endforeach;endif;?></tbody></table></div></div></div>
<div class="panel"><div class="ph"><h2>5. ZRA invoice verification</h2><p class="muted">Retrieve an invoice already posted to the configured controller.</p></div><div class="pb"><form method="post" class="fields"><input type="hidden" name="csrf" value="<?=zra_admin_h($_SESSION['zra_csrf'])?>"><input type="hidden" name="action" value="select_invoice"><div class="field"><label>Branch</label><select name="branch_id" required><option value="">Select branch</option><?php foreach($branches as $b):?><option value="<?=$b['id']?>"><?=zra_admin_h($b['branch_name'])?></option><?php endforeach;?></select></div><div class="field"><label>bhfId</label><input name="bhf_id" maxlength="3" required></div><div class="field"><label>SDC ID</label><input name="sdc_id" required></div><div class="field"><label>CIS Invoice Number</label><input name="cis_invoice" required></div><div><button class="btn"><i class="fa-solid fa-magnifying-glass"></i> Verify Invoice</button></div></form></div></div>
</div></main></div><script>
function setBhf(s){document.getElementById('bhf').value='';}
function setQueueBhf(s){document.getElementById('queueBhf').value='';}
</script></body></html>
